window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dfc07acf865e7a55"]={"versions": [{"id": "FIG-dfc07acf865e7a55", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponenten-Schnittstellendiagramm (AUTOSAR SWS Dem, Kapitel 8 <em>API specification – Configuration interfaces</em>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die konfigurierbaren Callback-Schnittstellen (Out-Notification-Interfaces) des <code>Diagnostic Event Manager</code> (Dem) gemäß <strong>SWS_Dem_00256</strong> im AUTOSAR Classic BSW. Das Diagramm modelliert das Entwurfsmuster der Inversion of Control (IoC): Der Dem ruft zustands- und datengetriebene Benachrichtigungsfunktionen auf, die wahlweise von BSW-Modulen (z. B. FiM, Dcm) oder Software-Komponenten (SWCs via RTE) bereitgestellt werden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>«module» Dem</code>:</strong> Kernkomponente des Diagnose-Stacks zur Erfassung, Filterung und Speicherung von Diagnose-Events und DTCs.</li>\n<li><strong><code>«interface» Dem_Configurable</code>:</strong> Virtuelle Schnittstelle, welche die konfigurierbaren Funktionspointer/Callbacks typisiert und bündelt.</li>\n<li><strong><code>«module» [SWC]</code>:</strong> Anwendungs-Softwarekomponente der Application Layer.</li>\n<li><strong><code>«module» [BSW]</code>:</strong> Basissoftware-Modul (z. B. Schichten unterhalb oder neben dem Dem).</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>Dem</code> $\\dashrightarrow$ <code>Dem_Configurable</code> (<code>«configurable»</code>):</strong> Konfigurationsabhängige Abhängigkeit. Der Dem ruft diese Schnittstellen auf; konkrete Funktionszeiger/Symbole werden über Parameter in den Konfigurationscontainern (z. B. <code>DemCallbackDTCStatusChanged</code>, <code>DemCallbackInitMonitorForEvent</code>, etc.) statisch zur Buildzeit parametriert.</li>\n<li><strong><code>[SWC]</code> / <code>[BSW]</code> $\\dashrightarrow$ <code>Dem_Configurable</code> (<code>«realize»</code>):</strong> SWCs und BSW-Module realisieren die Callback-Definitionen. Für BSWs erfolgt dies über direkte C-Funktionsdeklarationen (<code>&lt;Module&gt;_&lt;Function&gt;</code>), für SWCs über AUTOSAR Ports (Client-Server bzw. Event-Triggers via RTE).</li>\n</ul>\n<p class=\"fig-p\">#### Signatur- und Schnittstellen-Katalog (<code>Dem_Configurable</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>DTC-Status:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>Dem_CallbackDTCStatusChanged</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnDTCStatus(return, DTC, DTCStatusOld, DTCStatusNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Event-UDS-Status (General vs. Event-spezifisch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>Dem_CallbackEventStatusChanged</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus(return, EventId, EventStatusByteOld, EventStatusByteNew)</code></li>\n<li>Typ: <code>Dem_CallbackDemTriggerOnEventUdsStatus</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnEventUdsStatus(return, EventStatusByteOld, EventStatusByteNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Monitor-Status (General vs. Event-spezifisch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>Dem_CallbackDemGeneralTriggerOnMonitorStatus</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus(return, EventId)</code></li>\n<li>Typ: <code>Dem_CallbackDemTriggerOnMonitorStatus</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnMonitorStatus(return)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerzähler / Monitor-Steuerung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>Dem_CallbackGetFaultDetectionCounter</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemGetFaultDetectionCounter&lt;ForEvent&gt;(return, FaultDetectionCounter)</code> (Polling des Zählers bei monitorinternem Entprellen).</li>\n<li>Typ: <code>Dem_CallbackInitMonitorForEvent</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemInitMonitorFor&lt;EventName&gt;(return, InitMonitorReason)</code> (Reinitialisierung des Monitors bei Event-Clear, BusOff-Recovery etc.).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Datenänderung / Freeze Frames / DID:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>Dem_CallbackEventDataChanged</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnEventData(return, EventId)</code> (Trigger bei Update von FreezeFrame/ExtendedData).</li>\n<li>Typ: <code>Dem_CallbackReadDataElement</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemRead&lt;DataElement&gt;(Buffer, return)</code> (Synchrones Auslesen applikationsspezifischer Datenwerte für Snapshots/DIDs).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Freigabe & Fehlerkomponenten:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>Dem_CallbackClearEventAllowed</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemClearEventAllowed&lt;ForCondition&gt;(return, Allowed)</code> (Veto-Mechanismus gegen das Löschen von Events).</li>\n<li>Typ: <code>Dem_ComponentFailedCallbackFnc</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnComponentStatus(return, ComponentId)</code> (Benachrichtigung über Ausfall einer hierarchischen Diagnose-Komponente).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aufrufe erfolgen synchron aus dem Kontext des Dem (typischerweise aus <code>Dem_MainFunction()</code> oder direkt aus API-Aufrufen wie <code>Dem_SetEventStatus()</code> / <code>Dem_ClearDTC()</code>):</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">+--------------------------------------------------------------------------------+</p>\n<p class=\"fig-p\">| Synchroner Trigger-Ablauf                                                      |</p>\n<p class=\"fig-p\">+--------------------------------------------------------------------------------+</p>\n<ol class=\"fig-list\">\n<li>Zustandsänderung / Trigger im Dem</li>\n</ol>\n<p class=\"fig-p\">├─ EventStatus/MonitorStatus wechselt ──> Call DemTriggerOn[Monitor/EventUds]Status</p>\n<p class=\"fig-p\">├─ DTC-Statusbyte ändert sich         ──> Call DemTriggerOnDTCStatus (z. B. an Dcm/FiM)</p>\n<p class=\"fig-p\">├─ Re-Init Trigger (Clear / Enable)   ──> Call DemInitMonitorFor<EventName></p>\n<p class=\"fig-p\">├─ Snapshot-Speicherung gefordert     ──> Call DemRead<DataElement> (synchroner Read)</p>\n<p class=\"fig-p\">├─ Clear-Kommando empfangen           ──> Call DemClearEventAllowed (Rückgabe: TRUE/FALSE)</p>\n<p class=\"fig-p\">└─ Komponentenausfall                 ──> Call DemTriggerOnComponentStatus</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Rückgabewerte & Flusssteuerung:</strong></li>\n<li>Callbacks wie <code>DemClearEventAllowed</code> evaluieren synchron einen Veto-Status (<code>Allowed = FALSE</code> bricht den Löschvorgang für dieses Event ab).</li>\n<li><code>DemRead&lt;DataElement&gt;</code> erfordert das synchrone Befüllen des Zielpuffers <code>Buffer</code> durch den Aufrufer (ohne blockierende Operationen).</li>\n<li>Status-Trigger (<code>TriggerOn...</code>) sind reine Benachrichtigungen (<code>Std_ReturnType</code> zur Bestätigung/Fehlerbehandlung).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration & Namenskonvention (SWS_Dem_00256):</strong></li>\n</ul>\n<p class=\"fig-p\">Die Platzhalter <code>&lt;Module&gt;</code>, <code>&lt;EventName&gt;</code>, <code>&lt;DataElement&gt;</code> und <code>&lt;ForCondition&gt;</code> werden im AUTOSAR-ECUC-Modell (unter <code>DemConfigSet / DemEventParameter / DemCallback...</code>) als Funktionszeiger oder C-Symbole konfiguriert. Wird ein Callback nicht konfiguriert, generiert der Dem keinen Funktionsaufruf (Nullpointer-Vermeidung durch Codegenerierung).</p>\n<ul class=\"fig-list\">\n<li><strong>Kontext & Laufzeitverhalten (Reentrancy & ISR):</strong></li>\n<li>Werden Events aus Interrupt-Kontexten oder Task-Ebenen via <code>Dem_SetEventStatus()</code> gemeldet, können Callbacks synchron im Kontext des Aufrufers ausgelöst werden (sofern nicht über das interne Dem-Event-Buffer-Handling in die <code>Dem_MainFunction()</code> entkoppelt).</li>\n<li>Callbacks müssen deterministisch, nicht-blockierend und reentrancy-sicher ausgeführt werden.</li>\n<li><strong>RTE-Integration für SWCs:</strong></li>\n</ul>\n<p class=\"fig-p\">SWC-Implementierungen binden diese Schnittstellen nicht als C-Funktionen ein, sondern über AUTOSAR Standard-Ports (z. B. <code>CallbackInitMonitorForEvent</code>, <code>CallbackClearEventAllowed</code>). Der RTE-Generator mapped die Ports auf die vom Dem erwarteten Callback-Signaturen.</p>\n<ul class=\"fig-list\">\n<li><strong>FiM / Dcm Kopplung:</strong></li>\n</ul>\n<p class=\"fig-p\"><code>DemTriggerOnDTCStatus</code> und <code>DemGeneralTriggerOnEventUdsStatus</code> dienen typischerweise der direkten Benachrichtigung des <code>Function Inhibition Manager</code> (FiM) zur Funktionsdeaktivierung bzw. des <code>Diagnostic Communication Manager</code> (Dcm) zur Konsistenzprüfung des UDS-Status.</p>"}, {"id": "FIG-e11d2566090f8052", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponenten-Schnittstellendiagramm (AUTOSAR SWS Dem, Kapitel 8 <em>API specification – Configuration interfaces</em>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die konfigurierbaren Callback-Schnittstellen (Out-Notification-Interfaces) des <code>Diagnostic Event Manager</code> (Dem) gemäß <strong>SWS_Dem_00256</strong> im AUTOSAR Classic BSW. Das Diagramm modelliert das Entwurfsmuster der Inversion of Control (IoC): Der Dem ruft zustands- und datengetriebene Benachrichtigungsfunktionen auf, die wahlweise von BSW-Modulen (z. B. FiM, Dcm) oder Software-Komponenten (SWCs via RTE) bereitgestellt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>«module» Dem</code>:</strong> Kernkomponente des Diagnose-Stacks zur Erfassung, Filterung und Speicherung von Diagnose-Events und DTCs.</li>\n<li><strong><code>«interface» Dem_Configurable</code>:</strong> Virtuelle Schnittstelle, welche die konfigurierbaren Funktionspointer/Callbacks typisiert und bündelt.</li>\n<li><strong><code>«module» [SWC]</code>:</strong> Anwendungs-Softwarekomponente der Application Layer.</li>\n<li><strong><code>«module» [BSW]</code>:</strong> Basissoftware-Modul (z. B. Schichten unterhalb oder neben dem Dem).</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>Dem</code> $\\dashrightarrow$ <code>Dem_Configurable</code> (<code>«configurable»</code>):</strong> Konfigurationsabhängige Abhängigkeit. Der Dem ruft diese Schnittstellen auf; konkrete Funktionszeiger/Symbole werden über Parameter in den Konfigurationscontainern (z. B. <code>DemCallbackDTCStatusChanged</code>, <code>DemCallbackInitMonitorForEvent</code>, etc.) statisch zur Buildzeit parametriert.</li>\n<li><strong><code>[SWC]</code> / <code>[BSW]</code> $\\dashrightarrow$ <code>Dem_Configurable</code> (<code>«realize»</code>):</strong> SWCs und BSW-Module realisieren die Callback-Definitionen. Für BSWs erfolgt dies über direkte C-Funktionsdeklarationen (<code>&lt;Module&gt;_&lt;Function&gt;</code>), für SWCs über AUTOSAR Ports (Client-Server bzw. Event-Triggers via RTE).</li>\n</ul>\n<p class=\"fig-p\">#### Signatur- und Schnittstellen-Katalog (<code>Dem_Configurable</code>)</p>\n<ol class=\"fig-list\">\n<li><strong>DTC-Status:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>Dem_CallbackDTCStatusChanged</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnDTCStatus(return, DTC, DTCStatusOld, DTCStatusNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Event-UDS-Status (General vs. Event-spezifisch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>Dem_CallbackEventStatusChanged</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus(return, EventId, EventStatusByteOld, EventStatusByteNew)</code></li>\n<li>Typ: <code>Dem_CallbackDemTriggerOnEventUdsStatus</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnEventUdsStatus(return, EventStatusByteOld, EventStatusByteNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Monitor-Status (General vs. Event-spezifisch):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>Dem_CallbackDemGeneralTriggerOnMonitorStatus</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus(return, EventId)</code></li>\n<li>Typ: <code>Dem_CallbackDemTriggerOnMonitorStatus</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnMonitorStatus(return)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Fehlerzähler / Monitor-Steuerung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>Dem_CallbackGetFaultDetectionCounter</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemGetFaultDetectionCounter&lt;ForEvent&gt;(return, FaultDetectionCounter)</code> (Polling des Zählers bei monitorinternem Entprellen).</li>\n<li>Typ: <code>Dem_CallbackInitMonitorForEvent</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemInitMonitorFor&lt;EventName&gt;(return, InitMonitorReason)</code> (Reinitialisierung des Monitors bei Event-Clear, BusOff-Recovery etc.).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Datenänderung / Freeze Frames / DID:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>Dem_CallbackEventDataChanged</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnEventData(return, EventId)</code> (Trigger bei Update von FreezeFrame/ExtendedData).</li>\n<li>Typ: <code>Dem_CallbackReadDataElement</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemRead&lt;DataElement&gt;(Buffer, return, monitorData0)</code> (Synchrones Auslesen applikationsspezifischer Datenwerte unter Berücksichtigung von monitorspezifischen Daten für Freeze Frames oder Extended Data Records).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Komponentenstatus:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>Dem_ComponentFailedCallbackFnc</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnComponentStatus(return, ComponentId)</code> (Benachrichtigung über Ausfall einer überwachten Komponente).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Event-Clear-Berechtigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Typ: <code>Dem_CallbackClearEventAllowed</code></li>\n<li>Signatur: <code>&lt;Module&gt;_DemClearEventAllowed&lt;ForCondition&gt;(return, Allowed)</code> (Rückfrage vor dem Löschen eines Diagnose-Events zur Validierung von Umgebungsbedingungen).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aufrufe erfolgen synchron aus dem Kontext des Dem (typischerweise aus <code>Dem_MainFunction()</code> oder direkt aus API-Aufrufen wie <code>Dem_SetEventStatus()</code> / <code>Dem_ClearDTC()</code>):</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">+--------------------------------------------------------------------------------+</p>\n<p class=\"fig-p\">| Synchroner Trigger-Ablauf                                                      |</p>\n<p class=\"fig-p\">+--------------------------------------------------------------------------------+</p>\n<ol class=\"fig-list\">\n<li>Zustandsänderung / Trigger im Dem</li>\n</ol>\n<p class=\"fig-p\">├─ EventStatus/MonitorStatus wechselt ──> Call DemTriggerOn[Monitor/EventUds]Status</p>\n<p class=\"fig-p\">├─ DTC-Statusbyte ändert sich         ──> Call DemTriggerOnDTCStatus (z. B. an Dcm/FiM)</p>\n<p class=\"fig-p\">├─ Re-Init Trigger (Clear / Enable)   ──> Call DemInitMonitorFor<EventName></p>\n<p class=\"fig-p\">├─ Snapshot-Speicherung gefordert     ──> Call DemRead<DataElement> (synchroner Read)</p>\n<p class=\"fig-p\">├─ Clear-Kommando empfangen           ──> Call DemClearEventAllowed (Rückgabe: TRUE/FALSE)</p>\n<p class=\"fig-p\">└─ Komponentenausfall                 ──> Call DemTriggerOnComponentStatus</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Rückgabewerte & Flusssteuerung:</strong></li>\n<li>Callbacks wie <code>DemClearEventAllowed</code> evaluieren synchron einen Veto-Status (<code>Allowed = FALSE</code> bricht den Löschvorgang für dieses Event ab).</li>\n<li><code>DemRead&lt;DataElement&gt;</code> erfordert das synchrone Befüllen des Zielpuffers <code>Buffer</code> durch den Aufrufer (ohne blockierende Operationen).</li>\n<li>Status-Trigger (<code>TriggerOn...</code>) sind reine Benachrichtigungen (<code>Std_ReturnType</code> zur Bestätigung/Fehlerbehandlung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration & Namenskonvention (SWS_Dem_00256):</strong></li>\n</ul>\n<p class=\"fig-p\">Die Platzhalter <code>&lt;Module&gt;</code>, <code>&lt;EventName&gt;</code>, <code>&lt;DataElement&gt;</code> und <code>&lt;ForCondition&gt;</code> werden im AUTOSAR-ECUC-Modell (unter <code>DemConfigSet / DemEventParameter / DemCallback...</code>) als Funktionszeiger oder C-Symbole konfiguriert. Wird ein Callback nicht konfiguriert, generiert der Dem keinen Funktionsaufruf (Nullpointer-Vermeidung durch Codegenerierung).</p>\n<ul class=\"fig-list\">\n<li><strong>Kontext & Laufzeitverhalten (Reentrancy & ISR):</strong></li>\n<li>Werden Events aus Interrupt-Kontexten oder Task-Ebenen via <code>Dem_SetEventStatus()</code> gemeldet, können Callbacks synchron im Kontext des Aufrufers ausgelöst werden (sofern nicht über das interne Dem-Event-Buffer-Handling in die <code>Dem_MainFunction()</code> entkoppelt).</li>\n<li>Callbacks müssen deterministisch, nicht-blockierend und reentrancy-sicher ausgeführt werden.</li>\n<li><strong>RTE-Integration für SWCs:</strong></li>\n</ul>\n<p class=\"fig-p\">SWC-Implementierungen binden diese Schnittstellen nicht als C-Funktionen ein, sondern über AUTOSAR Standard-Ports (z. B. <code>CallbackInitMonitorForEvent</code>, <code>CallbackClearEventAllowed</code>). Der RTE-Generator mapped die Ports auf die vom Dem erwarteten Callback-Signaturen.</p>\n<ul class=\"fig-list\">\n<li><strong>FiM / Dcm Kopplung:</strong></li>\n</ul>\n<p class=\"fig-p\"><code>DemTriggerOnDTCStatus</code> und <code>DemGeneralTriggerOnEventUdsStatus</code> dienen typischerweise der direkten Benachrichtigung des <code>Function Inhibition Manager</code> (FiM) zur Funktionsdeaktivierung bzw. des <code>Diagnostic Communication Manager</code> (Dcm) zur Konsistenzprüfung des UDS-Status.</p>"}, {"id": "FIG-5b5ac5497f1d4642", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponenten-Schnittstellendiagramm (AUTOSAR SWS Dem, Kapitel 8 <em>API specification – Configuration interfaces</em>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die konfigurierbaren Callback-Schnittstellen (Out-Notification-Interfaces) des <code>Diagnostic Event Manager</code> (Dem) gemäß <strong>SWS_Dem_00256</strong> im AUTOSAR Classic BSW. Das Diagramm modelliert das Entwurfsmuster der Inversion of Control (IoC): Der Dem ruft zustands- und datengetriebene Benachrichtigungsfunktionen auf, die wahlweise von BSW-Modulen (z. B. FiM, Dcm) oder Software-Komponenten (SWCs via RTE) bereitgestellt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>«module» Dem</code>:</strong> Kernkomponente des Diagnose-Stacks zur Erfassung, Filterung und Speicherung von Diagnose-Events und DTCs.</li>\n<li><strong><code>«interface» Dem_Configurable</code>:</strong> Virtuelle Schnittstelle zur Bündelung der konfigurierbaren Callback-Schnittstellen. Im oberen Schnittstellenkasten sind die Callback-Typen aufgeführt:</li>\n<li><code>&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus</code></li>\n<li><code>&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus</code></li>\n<li><code>&lt;Module&gt;_DemTriggerOnDTCStatus</code></li>\n<li><code>&lt;Module&gt;_DemTriggerOnEventData</code></li>\n<li><code>&lt;Module&gt;_DemTriggerOnEventUdsStatus</code></li>\n<li><code>&lt;Module&gt;_DemTriggerOnMonitorStatus</code></li>\n<li><code>Dem_CallbackClearEventAllowed</code></li>\n<li><code>Dem_CallbackGetFaultDetectionCounter</code></li>\n<li><code>Dem_CallbackInitMonitorForEvent</code></li>\n<li><code>Dem_CallbackReadDataElement</code></li>\n<li><code>Dem_ComponentFailedCallbackFnc</code></li>\n<li><strong><code>«module» [SWC]</code>:</strong> Anwendungs-Softwarekomponente der Application Layer.</li>\n<li><strong><code>«module» [BSW]</code>:</strong> Basissoftware-Modul.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>Dem</code> $\\dashrightarrow$ <code>Dem_Configurable</code> (<code>«configurable»</code>):</strong> Konfigurationsabhängige Abhängigkeit des Dem auf die Callback-Schnittstellen.</li>\n<li><strong><code>[SWC]</code> / <code>[BSW]</code> $\\dashrightarrow$ <code>Dem_Configurable</code> (<code>«realize»</code>):</strong> Realisierung der Callbacks durch C-Funktionen (<code>BSW</code>) oder Ports via RTE (<code>SWC</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Signatur- und Schnittstellen-Katalog (<code>Dem_Configurable</code>)</p>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnDTCStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnDTCStatus(return, DTC, DTCStatusOld, DTCStatusNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus(return, EventId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnEventUdsStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnEventUdsStatus(return, EventStatusByteOld, EventStatusByteNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnMonitorStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnMonitorStatus(return)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::Dem_CallbackReadDataElement</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemRead&lt;DataElement&gt;(Buffer, return, monitorData0)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnEventData</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnEventData(return, EventId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::Dem_ComponentFailedCallbackFnc</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnComponentStatus(return, ComponentId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::Dem_CallbackClearEventAllowed</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemClearEventAllowed&lt;ForCondition&gt;(return, Allowed)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::Dem_CallbackGetFaultDetectionCounter</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGetFaultDetectionCounter&lt;ForEvent&gt;(return, FaultDetectionCounter)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus(return, EventId, EventStatusByteOld, EventStatusByteNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::Dem_CallbackInitMonitorForEvent</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemInitMonitorFor&lt;EventName&gt;(return, InitMonitorReason)</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aufrufe erfolgen synchron aus dem Kontext des Dem (typischerweise aus <code>Dem_MainFunction()</code> oder direkt aus API-Aufrufen wie <code>Dem_SetEventStatus()</code> / <code>Dem_ClearDTC()</code>):</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">+--------------------------------------------------------------------------------+</p>\n<p class=\"fig-p\">| Synchroner Trigger-Ablauf                                                      |</p>\n<p class=\"fig-p\">+--------------------------------------------------------------------------------+</p>\n<ol class=\"fig-list\">\n<li>Zustandsänderung / Trigger im Dem</li>\n</ol>\n<p class=\"fig-p\">├─ EventStatus/MonitorStatus wechselt ──> Call DemTriggerOn[Monitor/EventUds]Status</p>\n<p class=\"fig-p\">├─ DTC-Statusbyte ändert sich         ──> Call DemTriggerOnDTCStatus (z. B. an Dcm/FiM)</p>\n<p class=\"fig-p\">├─ Re-Init Trigger (Clear / Enable)   ──> Call DemInitMonitorFor<EventName></p>\n<p class=\"fig-p\">├─ Snapshot-Speicherung gefordert     ──> Call DemRead<DataElement> (synchroner Read)</p>\n<p class=\"fig-p\">├─ Clear-Kommando empfangen           ──> Call DemClearEventAllowed (Rückgabe: TRUE/FALSE)</p>\n<p class=\"fig-p\">└─ Komponentenausfall                 ──> Call DemTriggerOnComponentStatus</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Rückgabewerte & Flusssteuerung:</strong></li>\n<li>Callbacks wie <code>DemClearEventAllowed</code> evaluieren synchron einen Veto-Status (<code>Allowed = FALSE</code> bricht den Löschvorgang für dieses Event ab).</li>\n<li><code>DemRead&lt;DataElement&gt;</code> erfordert das synchrone Befüllen des Zielpuffers <code>Buffer</code> durch den Aufrufer (ohne blockierende Operationen).</li>\n<li>Status-Trigger (<code>TriggerOn...</code>) sind reine Benachrichtigungen (<code>Std_ReturnType</code> zur Bestätigung/Fehlerbehandlung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration & Namenskonvention (SWS_Dem_00256):</strong></li>\n</ul>\n<p class=\"fig-p\">Die Platzhalter <code>&lt;Module&gt;</code>, <code>&lt;EventName&gt;</code>, <code>&lt;DataElement&gt;</code> und <code>&lt;ForCondition&gt;</code> werden im AUTOSAR-ECUC-Modell (unter <code>DemConfigSet / DemEventParameter / DemCallback...</code>) als Funktionszeiger oder C-Symbole konfiguriert. Wird ein Callback nicht konfiguriert, generiert der Dem keinen Funktionsaufruf (Nullpointer-Vermeidung durch Codegenerierung).</p>\n<ul class=\"fig-list\">\n<li><strong>Kontext & Laufzeitverhalten (Reentrancy & ISR):</strong></li>\n<li>Werden Events aus Interrupt-Kontexten oder Task-Ebenen via <code>Dem_SetEventStatus()</code> gemeldet, können Callbacks synchron im Kontext des Aufrufers ausgelöst werden (sofern nicht über das interne Dem-Event-Buffer-Handling in die <code>Dem_MainFunction()</code> entkoppelt).</li>\n<li>Callbacks müssen deterministisch, nicht-blockierend und reentrancy-sicher ausgeführt werden.</li>\n<li><strong>RTE-Integration für SWCs:</strong></li>\n</ul>\n<p class=\"fig-p\">SWC-Implementierungen binden diese Schnittstellen nicht als C-Funktionen ein, sondern über AUTOSAR Standard-Ports (z. B. <code>CallbackInitMonitorForEvent</code>, <code>CallbackClearEventAllowed</code>). Der RTE-Generator mapped die Ports auf die vom Dem erwarteten Callback-Signaturen.</p>\n<ul class=\"fig-list\">\n<li><strong>FiM / Dcm Kopplung:</strong></li>\n</ul>\n<p class=\"fig-p\"><code>DemTriggerOnDTCStatus</code> und <code>DemGeneralTriggerOnEventUdsStatus</code> dienen typischerweise der direkten Benachrichtigung des <code>Function Inhibition Manager</code> (FiM) zur Funktionsdeaktivierung bzw. des <code>Diagnostic Communication Manager</code> (Dcm) zur Konsistenzprüfung des UDS-Status.</p>"}, {"id": "FIG-3585db29196f5877", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponenten-Schnittstellendiagramm (AUTOSAR SWS Dem, Kapitel 8 <em>API specification – Configuration interfaces</em>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die konfigurierbaren Callback-Schnittstellen (Out-Notification-Interfaces) des <code>Diagnostic Event Manager</code> (Dem) gemäß <strong>SWS_Dem_00256</strong> im AUTOSAR Classic BSW. Das Diagramm modelliert das Entwurfsmuster der Inversion of Control (IoC): Der Dem ruft zustands- und datengetriebene Benachrichtigungsfunktionen auf, die wahlweise von BSW-Modulen (z. B. FiM, Dcm) oder Software-Komponenten (SWCs via RTE) bereitgestellt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>«module» Dem</code>:</strong> Kernkomponente des Diagnose-Stacks zur Erfassung, Filterung und Speicherung von Diagnose-Events und DTCs.</li>\n<li><strong><code>«interface» Dem_Configurable</code>:</strong> Virtuelle Schnittstelle zur Bündelung der konfigurierbaren Callback-Schnittstellen. Im oberen Schnittstellenkasten sind die Callback-Typen aufgeführt:</li>\n<li><code>&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus</code></li>\n<li><code>&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus</code></li>\n<li><code>&lt;Module&gt;_DemTriggerOnDTCStatus</code></li>\n<li><code>&lt;Module&gt;_DemTriggerOnEventData</code></li>\n<li><code>&lt;Module&gt;_DemTriggerOnEventUdsStatus</code></li>\n<li><code>&lt;Module&gt;_DemTriggerOnMonitorStatus</code></li>\n<li><code>Dem_CallbackClearEventAllowed</code></li>\n<li><code>Dem_CallbackGetFaultDetectionCounter</code></li>\n<li><code>Dem_CallbackInitMonitorForEvent</code></li>\n<li><code>Dem_CallbackReadDataElement</code></li>\n<li><code>Dem_ComponentFailedCallbackFnc</code></li>\n<li><strong><code>«module» [SWC]</code>:</strong> Anwendungs-Softwarekomponente der Application Layer.</li>\n<li><strong><code>«module» [BSW]</code>:</strong> Basissoftware-Modul.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>Dem</code> $\\dashrightarrow$ <code>Dem_Configurable</code> (<code>«configurable»</code>):</strong> Konfigurationsabhängige Abhängigkeit des Dem auf die Callback-Schnittstellen.</li>\n<li><strong><code>[SWC]</code> / <code>[BSW]</code> $\\dashrightarrow$ <code>Dem_Configurable</code> (<code>«realize»</code>):</strong> Realisierung der Callbacks durch C-Funktionen (<code>BSW</code>) oder Ports via RTE (<code>SWC</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Signatur- und Schnittstellen-Katalog (<code>Dem_Configurable</code>)</p>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnDTCStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnDTCStatus(return, DTC, DTCStatusOld, DTCStatusNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus(return, EventId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnEventUdsStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnEventUdsStatus(return, EventStatusByteOld, EventStatusByteNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnMonitorStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnMonitorStatus(return)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::Dem_CallbackReadDataElement</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemRead&lt;DataElement&gt;(Buffer, return, monitorData0)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnEventData</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnEventData(return, EventId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::Dem_ComponentFailedCallbackFnc</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnComponentStatus(return, ComponentId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::Dem_CallbackClearEventAllowed</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemClearEventAllowed&lt;ForCondition&gt;(return, Allowed)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::Dem_CallbackGetFaultDetectionCounter</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGetFaultDetectionCounter&lt;ForEvent&gt;(return, FaultDetectionCounter)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus(return, EventId, EventStatusByteOld, EventStatusByteNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::Dem_CallbackInitMonitorForEvent</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemInitMonitorFor&lt;EventName&gt;(return, InitMonitorReason)</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aufrufe erfolgen synchron aus dem Kontext des Dem (typischerweise aus <code>Dem_MainFunction()</code> oder direkt aus API-Aufrufen wie <code>Dem_SetEventStatus()</code> / <code>Dem_ClearDTC()</code>):</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">+--------------------------------------------------------------------------------+</p>\n<p class=\"fig-p\">| Synchroner Trigger-Ablauf                                                      |</p>\n<p class=\"fig-p\">+--------------------------------------------------------------------------------+</p>\n<ol class=\"fig-list\">\n<li>Zustandsänderung / Trigger im Dem</li>\n</ol>\n<p class=\"fig-p\">├─ EventStatus/MonitorStatus wechselt ──> Call DemTriggerOn[Monitor/EventUds]Status</p>\n<p class=\"fig-p\">├─ DTC-Statusbyte ändert sich         ──> Call DemTriggerOnDTCStatus (z. B. an Dcm/FiM)</p>\n<p class=\"fig-p\">├─ Re-Init Trigger (Clear / Enable)   ──> Call DemInitMonitorFor<EventName></p>\n<p class=\"fig-p\">├─ Snapshot-Speicherung gefordert     ──> Call DemRead<DataElement> (synchroner Read)</p>\n<p class=\"fig-p\">├─ Clear-Kommando empfangen           ──> Call DemClearEventAllowed (Rückgabe: TRUE/FALSE)</p>\n<p class=\"fig-p\">└─ Komponentenausfall                 ──> Call DemTriggerOnComponentStatus</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Rückgabewerte & Flusssteuerung:</strong></li>\n<li>Callbacks wie <code>DemClearEventAllowed</code> evaluieren synchron einen Veto-Status (<code>Allowed = FALSE</code> bricht den Löschvorgang für dieses Event ab).</li>\n<li><code>DemRead&lt;DataElement&gt;</code> erfordert das synchrone Befüllen des Zielpuffers <code>Buffer</code> durch den Aufrufer (ohne blockierende Operationen).</li>\n<li>Status-Trigger (<code>TriggerOn...</code>) sind reine Benachrichtigungen (<code>Std_ReturnType</code> zur Bestätigung/Fehlerbehandlung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration & Namenskonvention (SWS_Dem_00256):</strong></li>\n</ul>\n<p class=\"fig-p\">Die Platzhalter <code>&lt;Module&gt;</code>, <code>&lt;EventName&gt;</code>, <code>&lt;DataElement&gt;</code> und <code>&lt;ForCondition&gt;</code> werden im AUTOSAR-ECUC-Modell (unter <code>DemConfigSet / DemEventParameter / DemCallback...</code>) als Funktionszeiger oder C-Symbole konfiguriert. Wird ein Callback nicht konfiguriert, generiert der Dem keinen Funktionsaufruf (Nullpointer-Vermeidung durch Codegenerierung).</p>\n<ul class=\"fig-list\">\n<li><strong>Kontext & Laufzeitverhalten (Reentrancy & ISR):</strong></li>\n<li>Werden Events aus Interrupt-Kontexten oder Task-Ebenen via <code>Dem_SetEventStatus()</code> gemeldet, können Callbacks synchron im Kontext des Aufrufers ausgelöst werden (sofern nicht über das interne Dem-Event-Buffer-Handling in die <code>Dem_MainFunction()</code> entkoppelt).</li>\n<li>Callbacks müssen deterministisch, nicht-blockierend und reentrancy-sicher ausgeführt werden.</li>\n<li><strong>RTE-Integration für SWCs:</strong></li>\n</ul>\n<p class=\"fig-p\">SWC-Implementierungen binden diese Schnittstellen nicht als C-Funktionen ein, sondern über AUTOSAR Standard-Ports (z. B. <code>CallbackInitMonitorForEvent</code>, <code>CallbackClearEventAllowed</code>). Der RTE-Generator mapped die Ports auf die vom Dem erwarteten Callback-Signaturen.</p>\n<ul class=\"fig-list\">\n<li><strong>FiM / Dcm Kopplung:</strong></li>\n</ul>\n<p class=\"fig-p\"><code>DemTriggerOnDTCStatus</code> und <code>DemGeneralTriggerOnEventUdsStatus</code> dienen typischerweise der direkten Benachrichtigung des <code>Function Inhibition Manager</code> (FiM) zur Funktionsdeaktivierung bzw. des <code>Diagnostic Communication Manager</code> (Dcm) zur Konsistenzprüfung des UDS-Status.</p>"}, {"id": "FIG-bc74c034c4c63c91", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponenten-Schnittstellendiagramm (AUTOSAR SWS Dem, Kapitel 8 <em>API specification – Configuration interfaces</em>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die konfigurierbaren Callback-Schnittstellen (Out-Notification-Interfaces) des <code>Diagnostic Event Manager</code> (Dem) gemäß <strong>SWS_Dem_00256</strong> im AUTOSAR Classic BSW. Das Diagramm modelliert das Entwurfsmuster der Inversion of Control (IoC): Der Dem ruft zustands- und datengetriebene Benachrichtigungsfunktionen auf, die wahlweise von BSW-Modulen (z. B. FiM, Dcm) oder Software-Komponenten (SWCs via RTE) bereitgestellt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>«module» Dem</code>:</strong> Kernkomponente des Diagnose-Stacks zur Erfassung, Filterung und Speicherung von Diagnose-Events und DTCs.</li>\n<li><strong><code>«interface» Dem_Configurable</code>:</strong> Virtuelle Schnittstelle zur Bündelung der konfigurierbaren Callback-Schnittstellen (oberer Attribut-/Typbereich entfernt, enthält nur noch den Operationsbereich).</li>\n<li><strong><code>«module» [SWC]</code>:</strong> Anwendungs-Softwarekomponente der Application Layer.</li>\n<li><strong><code>«module» [BSW]</code>:</strong> Basissoftware-Modul.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>Dem</code> $\\dashrightarrow$ <code>Dem_Configurable</code> (<code>«configurable»</code>):</strong> Konfigurationsabhängige Abhängigkeit des Dem auf die Callback-Schnittstellen.</li>\n<li><strong><code>[SWC]</code> / <code>[BSW]</code> $\\dashrightarrow$ <code>Dem_Configurable</code> (<code>«realize»</code>):</strong> Realisierung der Callbacks durch C-Funktionen (<code>BSW</code>) oder Ports via RTE (<code>SWC</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Signatur- und Schnittstellen-Katalog (<code>Dem_Configurable</code>)</p>\n<p class=\"fig-p\">Alle elf Operationen sind einheitlich mit dem Scoping-Präfix <code>::&lt;Module&gt;_...</code> deklariert:</p>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnDTCStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnDTCStatus(return, DTC, DTCStatusOld, DTCStatusNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus(return, EventId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnEventUdsStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnEventUdsStatus(return, EventStatusByteOld, EventStatusByteNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnMonitorStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnMonitorStatus(return)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemRead&lt;DataElement&gt;</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemRead&lt;DataElement&gt;(Buffer, return, monitorData0)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnEventData</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnEventData(return, EventId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnComponentStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnComponentStatus(return, ComponentId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemClearEventAllowed&lt;ForCondition&gt;</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemClearEventAllowed&lt;ForCondition&gt;(return, Allowed)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemGetFaultDetectionCounter&lt;ForEvent&gt;</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGetFaultDetectionCounter&lt;ForEvent&gt;(return, FaultDetectionCounter)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus(return, EventId, EventStatusByteOld, EventStatusByteNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemInitMonitorFor&lt;EventName&gt;</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemInitMonitorFor&lt;EventName&gt;(return, InitMonitorReason)</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aufrufe erfolgen synchron aus dem Kontext des Dem (typischerweise aus <code>Dem_MainFunction()</code> oder direkt aus API-Aufrufen wie <code>Dem_SetEventStatus()</code> / <code>Dem_ClearDTC()</code>):</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">+--------------------------------------------------------------------------------+</p>\n<p class=\"fig-p\">| Synchroner Trigger-Ablauf                                                      |</p>\n<p class=\"fig-p\">+--------------------------------------------------------------------------------+</p>\n<ol class=\"fig-list\">\n<li>Zustandsänderung / Trigger im Dem</li>\n</ol>\n<p class=\"fig-p\">├─ EventStatus/MonitorStatus wechselt ──> Call DemTriggerOn[Monitor/EventUds]Status</p>\n<p class=\"fig-p\">├─ DTC-Statusbyte ändert sich         ──> Call DemTriggerOnDTCStatus (z. B. an Dcm/FiM)</p>\n<p class=\"fig-p\">├─ Re-Init Trigger (Clear / Enable)   ──> Call DemInitMonitorFor<EventName></p>\n<p class=\"fig-p\">├─ Snapshot-Speicherung gefordert     ──> Call DemRead<DataElement> (synchroner Read)</p>\n<p class=\"fig-p\">├─ Clear-Kommando empfangen           ──> Call DemClearEventAllowed (Rückgabe: TRUE/FALSE)</p>\n<p class=\"fig-p\">└─ Komponentenausfall                 ──> Call DemTriggerOnComponentStatus</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Rückgabewerte & Flusssteuerung:</strong></li>\n<li>Callbacks wie <code>DemClearEventAllowed</code> evaluieren synchron einen Veto-Status (<code>Allowed = FALSE</code> bricht den Löschvorgang für dieses Event ab).</li>\n<li><code>DemRead&lt;DataElement&gt;</code> erfordert das synchrone Befüllen des Zielpuffers <code>Buffer</code> durch den Aufrufer (ohne blockierende Operationen).</li>\n<li>Status-Trigger (<code>TriggerOn...</code>) sind reine Benachrichtigungen (<code>Std_ReturnType</code> zur Bestätigung/Fehlerbehandlung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration & Namenskonvention (SWS_Dem_00256):</strong></li>\n</ul>\n<p class=\"fig-p\">Die Platzhalter <code>&lt;Module&gt;</code>, <code>&lt;EventName&gt;</code>, <code>&lt;DataElement&gt;</code> und <code>&lt;ForCondition&gt;</code> werden im AUTOSAR-ECUC-Modell (unter <code>DemConfigSet / DemEventParameter / DemCallback...</code>) als Funktionszeiger oder C-Symbole konfiguriert. Wird ein Callback nicht konfiguriert, generiert der Dem keinen Funktionsaufruf (Nullpointer-Vermeidung durch Codegenerierung).</p>\n<ul class=\"fig-list\">\n<li><strong>Kontext & Laufzeitverhalten (Reentrancy & ISR):</strong></li>\n<li>Werden Events aus Interrupt-Kontexten oder Task-Ebenen via <code>Dem_SetEventStatus()</code> gemeldet, können Callbacks synchron im Kontext des Aufrufers ausgelöst werden (sofern nicht über das interne Dem-Event-Buffer-Handling in die <code>Dem_MainFunction()</code> entkoppelt).</li>\n<li>Callbacks müssen deterministisch, nicht-blockierend und reentrancy-sicher ausgeführt werden.</li>\n<li><strong>RTE-Integration für SWCs:</strong></li>\n</ul>\n<p class=\"fig-p\">SWC-Implementierungen binden diese Schnittstellen nicht als C-Funktionen ein, sondern über AUTOSAR Standard-Ports (z. B. <code>CallbackInitMonitorForEvent</code>, <code>CallbackClearEventAllowed</code>). Der RTE-Generator mapped die Ports auf die vom Dem erwarteten Callback-Signaturen.</p>\n<ul class=\"fig-list\">\n<li><strong>FiM / Dcm Kopplung:</strong></li>\n</ul>\n<p class=\"fig-p\"><code>DemTriggerOnDTCStatus</code> und <code>DemGeneralTriggerOnEventUdsStatus</code> dienen typischerweise der direkten Benachrichtigung des <code>Function Inhibition Manager</code> (FiM) zur Funktionsdeaktivierung bzw. des <code>Diagnostic Communication Manager</code> (Dcm) zur Konsistenzprüfung des UDS-Status.</p>"}, {"id": "FIG-f4fd33b3e6ad34c7", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponenten-Schnittstellendiagramm (AUTOSAR SWS Dem, Kapitel 8 <em>API specification – Configuration interfaces</em>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die konfigurierbaren Callback-Schnittstellen (Out-Notification-Interfaces) des <code>Diagnostic Event Manager</code> (Dem) gemäß <strong>SWS_Dem_00256</strong> im AUTOSAR Classic BSW. Das Diagramm modelliert das Entwurfsmuster der Inversion of Control (IoC): Der Dem ruft zustands- und datengetriebene Benachrichtigungsfunktionen auf, die wahlweise von BSW-Modulen (z. B. FiM, Dcm) oder Software-Komponenten (SWCs via RTE) bereitgestellt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>«module» Dem</code>:</strong> Kernkomponente des Diagnose-Stacks zur Erfassung, Filterung und Speicherung von Diagnose-Events und DTCs.</li>\n<li><strong><code>«interface» Dem_Configurable</code>:</strong> Virtuelle Schnittstelle zur Bündelung der konfigurierbaren Callback-Schnittstellen (oberer Attribut-/Typbereich entfernt, enthält nur noch den Operationsbereich).</li>\n<li><strong><code>«module» [SWC]</code>:</strong> Anwendungs-Softwarekomponente der Application Layer.</li>\n<li><strong><code>«module» [BSW]</code>:</strong> Basissoftware-Modul.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>Dem</code> $\\dashrightarrow$ <code>Dem_Configurable</code> (<code>«configurable»</code>):</strong> Konfigurationsabhängige Abhängigkeit des Dem auf die Callback-Schnittstellen.</li>\n<li><strong><code>[SWC]</code> / <code>[BSW]</code> $\\dashrightarrow$ <code>Dem_Configurable</code> (<code>«realize»</code>):</strong> Realisierung der Callbacks durch C-Funktionen (<code>BSW</code>) oder Ports via RTE (<code>SWC</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Signatur- und Schnittstellen-Katalog (<code>Dem_Configurable</code>)</p>\n<p class=\"fig-p\">Alle elf Operationen sind einheitlich mit dem Scoping-Präfix <code>::&lt;Module&gt;_...</code> deklariert:</p>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnDTCStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnDTCStatus(return, DTC, DTCStatusOld, DTCStatusNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus(return, EventId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnEventUdsStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnEventUdsStatus(return, EventStatusByteOld, EventStatusByteNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnMonitorStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnMonitorStatus(return)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemRead&lt;DataElement&gt;</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemRead&lt;DataElement&gt;(Buffer, return, monitorData0)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnEventData</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnEventData(return, EventId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnComponentStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnComponentStatus(return, ComponentId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemClearEventAllowed&lt;ForCondition&gt;</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemClearEventAllowed&lt;ForCondition&gt;(return, Allowed)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemGetFaultDetectionCounter&lt;ForEvent&gt;</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGetFaultDetectionCounter&lt;ForEvent&gt;(return, FaultDetectionCounter)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus(return, EventId, EventStatusByteOld, EventStatusByteNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemInitMonitorFor&lt;EventName&gt;</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemInitMonitorFor&lt;EventName&gt;(return, InitMonitorReason)</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aufrufe erfolgen synchron aus dem Kontext des Dem (typischerweise aus <code>Dem_MainFunction()</code> oder direkt aus API-Aufrufen wie <code>Dem_SetEventStatus()</code> / <code>Dem_ClearDTC()</code>):</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">+--------------------------------------------------------------------------------+</p>\n<p class=\"fig-p\">| Synchroner Trigger-Ablauf                                                      |</p>\n<p class=\"fig-p\">+--------------------------------------------------------------------------------+</p>\n<ol class=\"fig-list\">\n<li>Zustandsänderung / Trigger im Dem</li>\n</ol>\n<p class=\"fig-p\">├─ EventStatus/MonitorStatus wechselt ──> Call DemTriggerOn[Monitor/EventUds]Status</p>\n<p class=\"fig-p\">├─ DTC-Statusbyte ändert sich         ──> Call DemTriggerOnDTCStatus (z. B. an Dcm/FiM)</p>\n<p class=\"fig-p\">├─ Re-Init Trigger (Clear / Enable)   ──> Call DemInitMonitorFor<EventName></p>\n<p class=\"fig-p\">├─ Snapshot-Speicherung gefordert     ──> Call DemRead<DataElement> (synchroner Read)</p>\n<p class=\"fig-p\">├─ Clear-Kommando empfangen           ──> Call DemClearEventAllowed (Rückgabe: TRUE/FALSE)</p>\n<p class=\"fig-p\">└─ Komponentenausfall                 ──> Call DemTriggerOnComponentStatus</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Rückgabewerte & Flusssteuerung:</strong></li>\n<li>Callbacks wie <code>DemClearEventAllowed</code> evaluieren synchron einen Veto-Status (<code>Allowed = FALSE</code> bricht den Löschvorgang für dieses Event ab).</li>\n<li><code>DemRead&lt;DataElement&gt;</code> erfordert das synchrone Befüllen des Zielpuffers <code>Buffer</code> durch den Aufrufer (ohne blockierende Operationen).</li>\n<li>Status-Trigger (<code>TriggerOn...</code>) sind reine Benachrichtigungen (<code>Std_ReturnType</code> zur Bestätigung/Fehlerbehandlung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration & Namenskonvention (SWS_Dem_00256):</strong></li>\n</ul>\n<p class=\"fig-p\">Die Platzhalter <code>&lt;Module&gt;</code>, <code>&lt;EventName&gt;</code>, <code>&lt;DataElement&gt;</code> und <code>&lt;ForCondition&gt;</code> werden im AUTOSAR-ECUC-Modell (unter <code>DemConfigSet / DemEventParameter / DemCallback...</code>) als Funktionszeiger oder C-Symbole konfiguriert. Wird ein Callback nicht konfiguriert, generiert der Dem keinen Funktionsaufruf (Nullpointer-Vermeidung durch Codegenerierung).</p>\n<ul class=\"fig-list\">\n<li><strong>Kontext & Laufzeitverhalten (Reentrancy & ISR):</strong></li>\n<li>Werden Events aus Interrupt-Kontexten oder Task-Ebenen via <code>Dem_SetEventStatus()</code> gemeldet, können Callbacks synchron im Kontext des Aufrufers ausgelöst werden (sofern nicht über das interne Dem-Event-Buffer-Handling in die <code>Dem_MainFunction()</code> entkoppelt).</li>\n<li>Callbacks müssen deterministisch, nicht-blockierend und reentrancy-sicher ausgeführt werden.</li>\n<li><strong>RTE-Integration für SWCs:</strong></li>\n</ul>\n<p class=\"fig-p\">SWC-Implementierungen binden diese Schnittstellen nicht als C-Funktionen ein, sondern über AUTOSAR Standard-Ports (z. B. <code>CallbackInitMonitorForEvent</code>, <code>CallbackClearEventAllowed</code>). Der RTE-Generator mapped die Ports auf die vom Dem erwarteten Callback-Signaturen.</p>\n<ul class=\"fig-list\">\n<li><strong>FiM / Dcm Kopplung:</strong></li>\n</ul>\n<p class=\"fig-p\"><code>DemTriggerOnDTCStatus</code> und <code>DemGeneralTriggerOnEventUdsStatus</code> dienen typischerweise der direkten Benachrichtigung des <code>Function Inhibition Manager</code> (FiM) zur Funktionsdeaktivierung bzw. des <code>Diagnostic Communication Manager</code> (Dcm) zur Konsistenzprüfung des UDS-Status.</p>"}, {"id": "FIG-6a9900c22172d542", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm / Komponenten-Schnittstellendiagramm (AUTOSAR SWS Dem, Kapitel 8 <em>API specification – Configuration interfaces</em>).</li>\n<li><strong>Architektur-Kontext:</strong> Spezifiziert die konfigurierbaren Callback-Schnittstellen (Out-Notification-Interfaces) des <code>Diagnostic Event Manager</code> (Dem) gemäß <strong>SWS_Dem_00256</strong> im AUTOSAR Classic BSW. Das Diagramm modelliert das Entwurfsmuster der Inversion of Control (IoC): Der Dem ruft zustands- und datengetriebene Benachrichtigungsfunktionen auf, die wahlweise von BSW-Modulen (z. B. FiM, Dcm) oder Software-Komponenten (SWCs via RTE) bereitgestellt werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>«module» Dem</code>:</strong> Kernkomponente des Diagnose-Stacks zur Erfassung, Filterung und Speicherung von Diagnose-Events und DTCs.</li>\n<li><strong><code>«interface» Dem_Configurable</code>:</strong> Virtuelle Schnittstelle zur Bündelung der konfigurierbaren Callback-Schnittstellen (oberer Attribut-/Typbereich entfernt, enthält nur noch den Operationsbereich).</li>\n<li><strong><code>«module» [SWC]</code>:</strong> Anwendungs-Softwarekomponente der Application Layer.</li>\n<li><strong><code>«module» [BSW]</code>:</strong> Basissoftware-Modul.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>Dem</code> $\\dashrightarrow$ <code>Dem_Configurable</code> (<code>«configurable»</code>):</strong> Konfigurationsabhängige Abhängigkeit des Dem auf die Callback-Schnittstellen.</li>\n<li><strong><code>[SWC]</code> / <code>[BSW]</code> $\\dashrightarrow$ <code>Dem_Configurable</code> (<code>«realize»</code>):</strong> Realisierung der Callbacks durch C-Funktionen (<code>BSW</code>) oder Ports via RTE (<code>SWC</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Signatur- und Schnittstellen-Katalog (<code>Dem_Configurable</code>)</p>\n<p class=\"fig-p\">Alle elf Operationen sind einheitlich mit dem Scoping-Präfix <code>::&lt;Module&gt;_...</code> deklariert:</p>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnDTCStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnDTCStatus(return, DTC, DTCStatusOld, DTCStatusNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus(return, EventId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnEventUdsStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnEventUdsStatus(return, EventStatusByteOld, EventStatusByteNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnMonitorStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnMonitorStatus(return)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemRead&lt;DataElement&gt;</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemRead&lt;DataElement&gt;(Buffer, return, monitorData0)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnEventData</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnEventData(return, EventId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemTriggerOnComponentStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemTriggerOnComponentStatus(return, ComponentId)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemClearEventAllowed&lt;ForCondition&gt;</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemClearEventAllowed&lt;ForCondition&gt;(return, Allowed)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemGetFaultDetectionCounter&lt;ForEvent&gt;</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGetFaultDetectionCounter&lt;ForEvent&gt;(return, FaultDetectionCounter)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus(return, EventId, EventStatusByteOld, EventStatusByteNew)</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>::&lt;Module&gt;_DemInitMonitorFor&lt;EventName&gt;</code></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Signatur: <code>&lt;Module&gt;_DemInitMonitorFor&lt;EventName&gt;(return, InitMonitorReason)</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aufrufe erfolgen synchron aus dem Kontext des Dem (typischerweise aus <code>Dem_MainFunction()</code> oder direkt aus API-Aufrufen wie <code>Dem_SetEventStatus()</code> / <code>Dem_ClearDTC()</code>):</p>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">+--------------------------------------------------------------------------------+</p>\n<p class=\"fig-p\">| Synchroner Trigger-Ablauf                                                      |</p>\n<p class=\"fig-p\">+--------------------------------------------------------------------------------+</p>\n<ol class=\"fig-list\">\n<li>Zustandsänderung / Trigger im Dem</li>\n</ol>\n<p class=\"fig-p\">├─ EventStatus/MonitorStatus wechselt ──> Call DemTriggerOn[Monitor/EventUds]Status</p>\n<p class=\"fig-p\">├─ DTC-Statusbyte ändert sich         ──> Call DemTriggerOnDTCStatus (z. B. an Dcm/FiM)</p>\n<p class=\"fig-p\">├─ Re-Init Trigger (Clear / Enable)   ──> Call DemInitMonitorFor<EventName></p>\n<p class=\"fig-p\">├─ Snapshot-Speicherung gefordert     ──> Call DemRead<DataElement> (synchroner Read)</p>\n<p class=\"fig-p\">├─ Clear-Kommando empfangen           ──> Call DemClearEventAllowed (Rückgabe: TRUE/FALSE)</p>\n<p class=\"fig-p\">└─ Komponentenausfall                 ──> Call DemTriggerOnComponentStatus</p>\n<p class=\"fig-p\">```</p>\n<ul class=\"fig-list\">\n<li><strong>Rückgabewerte & Flusssteuerung:</strong></li>\n<li>Callbacks wie <code>DemClearEventAllowed</code> evaluieren synchron einen Veto-Status (<code>Allowed = FALSE</code> bricht den Löschvorgang für dieses Event ab).</li>\n<li><code>DemRead&lt;DataElement&gt;</code> erfordert das synchrone Befüllen des Zielpuffers <code>Buffer</code> durch den Aufrufer (ohne blockierende Operationen).</li>\n<li>Status-Trigger (<code>TriggerOn...</code>) sind reine Benachrichtigungen (<code>Std_ReturnType</code> zur Bestätigung/Fehlerbehandlung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration & Namenskonvention (SWS_Dem_00256):</strong></li>\n</ul>\n<p class=\"fig-p\">Die Platzhalter <code>&lt;Module&gt;</code>, <code>&lt;EventName&gt;</code>, <code>&lt;DataElement&gt;</code> und <code>&lt;ForCondition&gt;</code> werden im AUTOSAR-ECUC-Modell (unter <code>DemConfigSet / DemEventParameter / DemCallback...</code>) als Funktionszeiger oder C-Symbole konfiguriert. Wird ein Callback nicht konfiguriert, generiert der Dem keinen Funktionsaufruf (Nullpointer-Vermeidung durch Codegenerierung).</p>\n<ul class=\"fig-list\">\n<li><strong>Kontext & Laufzeitverhalten (Reentrancy & ISR):</strong></li>\n<li>Werden Events aus Interrupt-Kontexten oder Task-Ebenen via <code>Dem_SetEventStatus()</code> gemeldet, können Callbacks synchron im Kontext des Aufrufers ausgelöst werden (sofern nicht über das interne Dem-Event-Buffer-Handling in die <code>Dem_MainFunction()</code> entkoppelt).</li>\n<li>Callbacks müssen deterministisch, nicht-blockierend und reentrancy-sicher ausgeführt werden.</li>\n<li><strong>RTE-Integration für SWCs:</strong></li>\n</ul>\n<p class=\"fig-p\">SWC-Implementierungen binden diese Schnittstellen nicht als C-Funktionen ein, sondern über AUTOSAR Standard-Ports (z. B. <code>CallbackInitMonitorForEvent</code>, <code>CallbackClearEventAllowed</code>). Der RTE-Generator mapped die Ports auf die vom Dem erwarteten Callback-Signaturen.</p>\n<ul class=\"fig-list\">\n<li><strong>FiM / Dcm Kopplung:</strong></li>\n</ul>\n<p class=\"fig-p\"><code>DemTriggerOnDTCStatus</code> und <code>DemGeneralTriggerOnEventUdsStatus</code> dienen typischerweise der direkten Benachrichtigung des <code>Function Inhibition Manager</code> (FiM) zur Funktionsdeaktivierung bzw. des <code>Diagnostic Communication Manager</code> (Dcm) zur Konsistenzprüfung des UDS-Status.</p>"}], "trans": [{"from": "FIG-dfc07acf865e7a55", "to": "FIG-e11d2566090f8052", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>Dem_Configurable</code>: Die Signatur von <code>&lt;Module&gt;_DemRead&lt;DataElement&gt;</code> wurde um den Parameter <code>monitorData0</code> erweitert (von <code>(Buffer, return)</code> auf <code>(Buffer, return, monitorData0)</code>).</li>\n</ul>"}, {"from": "FIG-e11d2566090f8052", "to": "FIG-5b5ac5497f1d4642", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>Dem_Configurable</code> (oberer Attributbereich): Umbenennung von sechs Callback-Typen auf das Muster <code>&lt;Module&gt;_...</code>:</li>\n<li><code>Dem_CallbackDTCStatusChanged</code> $\\rightarrow$ <code>&lt;Module&gt;_DemTriggerOnDTCStatus</code></li>\n<li><code>Dem_CallbackDemGeneralTriggerOnMonitorStatus</code> $\\rightarrow$ <code>&lt;Module&gt;_DemGeneralTriggerOnMonitorStatus</code></li>\n<li><code>Dem_CallbackDemTriggerOnEventUdsStatus</code> $\\rightarrow$ <code>&lt;Module&gt;_DemTriggerOnEventUdsStatus</code></li>\n<li><code>Dem_CallbackDemTriggerOnMonitorStatus</code> $\\rightarrow$ <code>&lt;Module&gt;_DemTriggerOnMonitorStatus</code></li>\n<li><code>Dem_CallbackEventDataChanged</code> $\\rightarrow$ <code>&lt;Module&gt;_DemTriggerOnEventData</code></li>\n<li><code>Dem_CallbackEventStatusChanged</code> $\\rightarrow$ <code>&lt;Module&gt;_DemGeneralTriggerOnEventUdsStatus</code></li>\n<li><code>Dem_Configurable</code> (unterer Operationsbereich): Anpassung der Scoping-Präfixe (<code>::&lt;Module&gt;_...</code> statt <code>::Dem_Callback...</code>) für die sechs umbenannten Operationen sowie veränderte vertikale Anordnungsreihenfolge der Operationen.</li>\n</ul>"}, {"from": "FIG-5b5ac5497f1d4642", "to": "FIG-3585db29196f5877", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3585db29196f5877", "to": "FIG-bc74c034c4c63c91", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>Dem_Configurable</code>: Vollständige Entfernung des oberen Attribut-/Typbereichs aus dem UML-Interface-Kasten.</li>\n<li><code>Dem_Configurable</code> (Operationsbereich): Harmonisierung der verbliebenen fünf Scoping-Präfixe von <code>::Dem_Callback...</code> bzw. <code>::Dem_Component...</code> auf <code>::&lt;Module&gt;_...</code>:</li>\n<li><code>::Dem_CallbackReadDataElement</code> $\\rightarrow$ <code>::&lt;Module&gt;_DemRead&lt;DataElement&gt;</code></li>\n<li><code>::Dem_ComponentFailedCallbackFnc</code> $\\rightarrow$ <code>::&lt;Module&gt;_DemTriggerOnComponentStatus</code></li>\n<li><code>::Dem_CallbackClearEventAllowed</code> $\\rightarrow$ <code>::&lt;Module&gt;_DemClearEventAllowed&lt;ForCondition&gt;</code></li>\n<li><code>::Dem_CallbackGetFaultDetectionCounter</code> $\\rightarrow$ <code>::&lt;Module&gt;_DemGetFaultDetectionCounter&lt;ForEvent&gt;</code></li>\n<li><code>::Dem_CallbackInitMonitorForEvent</code> $\\rightarrow$ <code>::&lt;Module&gt;_DemInitMonitorFor&lt;EventName&gt;</code></li>\n</ul>"}, {"from": "FIG-bc74c034c4c63c91", "to": "FIG-f4fd33b3e6ad34c7", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f4fd33b3e6ad34c7", "to": "FIG-6a9900c22172d542", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
